function openDB(){return new Promise((res,rej)=>{try{if(!('indexedDB' in window))return rej(Error('IndexedDB unavailable'));const r=indexedDB.open(dbName,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(storeName))r.result.createObjectStore(storeName,{keyPath:'id'})};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error||Error('IndexedDB unavailable'))}catch(e){rej(e)}})}
async function dbPut(v){try{const d=await openDB();return await new Promise((res,rej)=>{const t=d.transaction(storeName,'readwrite');t.objectStore(storeName).put(v);t.oncomplete=()=>res();t.onerror=()=>rej(t.error)})}catch(e){memPackages=memPackages.filter(x=>x.id!==v.id);memPackages.push(v)}}
async function dbAll(){try{const d=await openDB();return await new Promise((res,rej)=>{const r=d.transaction(storeName).objectStore(storeName).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}catch(e){return memPackages.slice()}}
async function dbDelete(id){try{const d=await openDB();return await new Promise((res,rej)=>{const t=d.transaction(storeName,'readwrite');t.objectStore(storeName).delete(id);t.oncomplete=res;t.onerror=()=>rej(t.error)})}catch(e){memPackages=memPackages.filter(x=>x.id!==id)}}
function examFull(x){return {TOEFL:'TOEFL iBT',SAT:'Digital SAT',AP:'AP Exams',ACT:'ACT Online'}[x]}
function examFamily(x){return {TOEFL:'TOEFL testing environment',SAT:'Bluebook testing environment',AP:'Bluebook AP testing environment',ACT:'ACT Gateway testing environment'}[x]}
function examAccent(x){return {TOEFL:'#2e686d',SAT:'#2f5fc7',AP:'#7a3346',ACT:'#173d5c'}[x]}
async function home(){stopTimer();tfStopPromptAudio();currentExam=null;const packs=await dbAll();const latest={};packs.sort((a,b)=>b.importedAt-a.importedAt).forEach(p=>latest[p.exam]??=p);const order=['TOEFL','SAT','AP','ACT'];app.innerHTML=`<div class="home launcherV2"><header class="launcherTop"><div class="launcherIdentity"><div class="launcherGlyph">ES</div><div><div class="launcherTitle">Exam Simulator</div><div class="launcherSub">Local assessment runtime</div></div></div><div class="launcherTools"><button class="launcherTextBtn" id="libraryBtn">Exam Library</button><button class="launcherImportBtn" id="importBtn">Import Exam Package</button></div></header><main class="launcherMain"><section class="launcherIntro"><div class="launcherEyebrow">TEST ENVIRONMENTS</div><h1>Select an exam.</h1><p>Each exam opens in its own testing interface, flow, tools, timing rules, and imported question package.</p></section><section class="examLauncherGrid">${order.map((x,i)=>`<button class="launcherExam launcher-${x.toLowerCase()}" style="--exam-accent:${examAccent(x)}" data-exam="${x}"><div class="launcherExamTop"><span class="launcherNumber">0${i+1}</span><span class="launcherMode">${latest[x]?'PACKAGE READY':'PREVIEW MODE'}</span></div><div class="launcherExamName">${examFull(x)}</div><div class="launcherExamFamily">${examFamily(x)}</div><div class="launcherExamRule"></div><div class="launcherExamBottom"><span class="launcherPackage">${latest[x]?escapeHtml(latest[x].title):'Built-in interface preview'}</span><span class="launcherArrow" aria-hidden="true">›</span></div></button>`).join('')}</section></main><footer class="launcherFoot"><div><span class="launcherDot"></span> Offline · Windows</div><div>v0.11.0 · BLUEBOOK SCREENSHOT-LOCK BUILD</div></footer></div>`;
$('.examLauncherGrid').onclick=e=>{const b=e.target.closest('[data-exam]');if(b)launchExam(b.dataset.exam,latest[b.dataset.exam]||null)};$('#importBtn').onclick=()=>packageInput.click();$('#libraryBtn').onclick=libraryModal}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function loading(exam,cb){const phases={TOEFL:['Initializing audio system','Preparing TOEFL interface','Loading test session'],SAT:['Preparing Bluebook interface','Loading test session','Checking local tools'],AP:['Preparing Bluebook AP interface','Loading test session','Checking local tools'],ACT:['Preparing Gateway interface','Loading test session','Checking local tools']}[exam]||['Preparing test environment','Loading session','Ready'];app.innerHTML=`<div class="loading loadingV2" style="--load-accent:${examAccent(exam)}"><div class="loadFrame"><div class="loadEyebrow">EXAM SIMULATOR</div><div class="loadMark">${examFull(exam)}</div><div class="loadFamily">${examFamily(exam)}</div><div class="loadTrack"><div class="loadBar"></div></div><div class="loadPhases">${phases.map((p,i)=>`<span><i>${i+1}</i>${escapeHtml(p)}</span>`).join('')}</div></div></div>`;setTimeout(cb,1200)}
function tfPrimeNarration(){try{if('speechSynthesis' in window){speechSynthesis.resume();speechSynthesis.getVoices()}}catch(e){}try{const C=window.AudioContext||window.webkitAudioContext;if(C){const c=new C();c.resume?.();const o=c.createOscillator(),g=c.createGain();g.gain.value=0;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.01);o.onended=()=>c.close()}}catch(e){}}
async function launchExam(exam,stored){currentExam=exam;if(exam==='TOEFL')tfPrimeNarration();loading(exam,async()=>{let pack=null;if(stored){try{pack=await decodePackage(stored.data,stored.kind)}catch(e){alert('Package could not be loaded: '+e.message)}} startShell(exam,pack)})}
function startShell(exam,pack){const base=JSON.parse(JSON.stringify(officialDefaults[exam]));if(pack?.manifest){base.title=pack.manifest.title||base.title;base.package=pack;base.settings=pack.manifest.settings||{};if(Array.isArray(pack.manifest.flow)&&pack.manifest.flow.length)base.steps=pack.manifest.flow}session={exam,base,stepIndex:-1,qIndex:0,answers:{},flags:{},routes:{},seconds:0,startedAt:Date.now(),packageId:pack?.manifest?.id||'demo',tfAssetPicks:{},tfTaskIntros:{}}; if(exam==='SAT'||exam==='AP')bbWelcome(); else if(exam==='ACT')actWelcome(); else tfWelcome()}
function bbWelcome(){app.innerHTML=`<div class="bbHome bbRefHome"><div class="bbHomeTop"><div class="bbWordmark"><span class="bbKite">◢</span> Bluebook</div><button class="bbPlain" id="exitHome">Return to Home</button></div><div class="bbHomeBody"><div class="bbHello">Your Tests</div><div class="bbHomeCard"><div class="bbCardTop"><div><div class="bbCardExam">${escapeHtml(session.base.title)}</div><div class="bbCardMeta">Today · Digital testing</div></div><div class="bbReady">Ready</div></div><div class="bbCardRule"></div><div class="bbCardRow"><div><div class="bbCardLabel">Test day check-in</div><div class="bbCardHelp">Your device is ready for check-in.</div></div><button class="bbAction" id="bbCheck">Check In</button></div></div></div></div>`;$('#bbCheck').onclick=bbRoomCode;$('#exitHome').onclick=home}
function bbRoomCode(){app.innerHTML=`<div class="bbRoomCode"><div class="bbRoomTop"><button class="bbPlain" id="roomHelp">?&nbsp; Help</button><button class="bbPlain" id="exitHome">Return to Home</button></div><main class="bbRoomMain"><h1>Room Code</h1><p>Enter the room code provided by your proctor.</p><div class="roomCodeBoxes">${Array.from({length:5},(_,i)=>`<input maxlength="1" value="${'TRAIN'[i]}">`).join('')}</div></main><div class="bbRoomFooter"><button class="bbRoomBack" id="roomBack">Back</button><div class="bbRoomProgress"><span>Step 4 of 11</span><div><i></i></div></div><button class="bbRoomNext" id="roomNext">Next</button></div></div>`;$('#roomBack').onclick=bbWelcome;$('#roomNext').onclick=bbStartCode;$('#exitHome').onclick=home;$('#roomHelp').onclick=helpModal;const a=[...document.querySelectorAll('.roomCodeBoxes input')];a.forEach((x,i)=>{x.oninput=()=>{x.value=x.value.toUpperCase().replace(/[^A-Z]/g,'').slice(0,1);if(x.value&&a[i+1])a[i+1].focus()}})}
function bbStartCode(){app.innerHTML=`<div class="bbStartExact"><button class="bbReturn" id="exitHome">Return to Home</button><div class="bbStartInner"><h1>Start Code</h1><p>Once the proctor shares the start code, enter it here to begin testing.</p><p class="bbStartSub">The start code contains numbers only.</p><div class="startCode exact">${Array.from({length:6},(_,i)=>`<input maxlength="1" inputmode="numeric" value="${[4,9,2,7,7,6][i]}">`).join('')}</div><button class="bbStartTest" id="startTest">Start Test</button></div><div class="bbBottomHelp">You can review the <u>instructions</u> that the proctor reads aloud.</div></div>`;$('#startTest').onclick=()=>bbPreparing(0);$('#exitHome').onclick=home;const ins=[...document.querySelectorAll('.startCode input')];ins.forEach((x,i)=>{x.oninput=()=>{x.value=x.value.replace(/\D/g,'').slice(0,1);if(x.value&&ins[i+1])ins[i+1].focus()};x.onkeydown=e=>{if(e.key==='Backspace'&&!x.value&&ins[i-1])ins[i-1].focus()}})}
function bbStepDuration(step){return Number(step?.durationSeconds??step?.duration??0)}
function bbCandidateName(){return session?.base?.settings?.candidateName||session?.base?.package?.manifest?.candidateName||'Test Taker'}
function bbIcon(name){const m={pen:'<svg viewBox="0 0 24 24"><path d="M4 17.2V20h2.8L17.7 9.1l-2.8-2.8L4 17.2Z"/><path d="m13.9 7.3 2.8 2.8 1.9-1.9c.5-.5.5-1.3 0-1.8l-1-1c-.5-.5-1.3-.5-1.8 0l-1.9 1.9Z"/></svg>',more:'<svg viewBox="0 0 24 24"><circle cx="12" cy="5" r="1.7"/><circle cx="12" cy="12" r="1.7"/><circle cx="12" cy="19" r="1.7"/></svg>',calc:'<svg viewBox="0 0 24 24"><rect x="5" y="3" width="14" height="18" rx="1"/><path d="M8 7h8M8 11h2m3 0h2m-7 4h2m3 0h2m-7 4h2m3 0h2"/></svg>',ref:'<svg viewBox="0 0 24 24"><path d="M5 4h10a3 3 0 0 1 3 3v13H8a3 3 0 0 1-3-3V4Z"/><path d="M8 8h7M8 12h7M8 16h5"/></svg>'};return `<span class="bbToolSvg">${m[name]||m.more}</span>`}
function bbMiniIcon(name){const p={down:'<path d="m6 9 6 6 6-6"/>',up:'<path d="m6 15 6-6 6 6"/>',expand:'<path d="M9 4H4v5M15 20h5v-5M4 9l6-6M20 15l-6 6"/>',home:'<path d="M3 11.5 12 4l9 7.5M6 10.5V20h12v-9.5M9.5 20v-6h5v6"/>'};return `<svg class="bbMiniSvg" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${p[name]||p.down}</svg>`}

function bbPreparing(idx){stopTimer();app.innerHTML=`<div class="bbPreparing"><button class="bbReturn" id="exitHome">Return to Home</button><h1>We're Preparing Your Test</h1><div class="bbPrepareCard"><div class="bbHourglass" aria-hidden="true"><svg viewBox="0 0 120 150"><path class="frame" fill="#d8e8f3" stroke="#555" stroke-width="4" d="M28 18h64v13H28zM28 119h64v13H28zM34 31c0 31 23 30 23 44s-23 14-23 44h52c0-30-23-30-23-44s23-13 23-44H34z"/><path class="sand" fill="#f17044" d="M43 39h34c-3 17-16 20-17 31-2-11-15-14-17-31Zm17 41 19 31H41l19-31Z"/><circle class="drop" fill="#f17044" cx="60" cy="76" r="2"/></svg></div><p>This may take up to a minute. Please don't<br>refresh this page or exit the app.</p></div></div>`;$('#exitHome').onclick=home;setTimeout(()=>{if(session&&(session.exam==='SAT'||session.exam==='AP'))bbDirections(idx)},1350)}
function bbDirectionCopy(st){if(session.exam==='AP'&&/free response/i.test(st.label||''))return `<p class="bbDirLead"><b>The directions that follow are what you will see on exam day.</b></p><p>${escapeHtml(st.label)} has ${st.count||questionCount(st)} questions. Read each question carefully and enter your response in the space provided.</p><p>You may use the tools provided in this application when they are permitted for this section. Reference information can be opened from the testing toolbar when available.</p><p>Credit depends on the quality and completeness of your responses. Show your work when the question requires it and clearly indicate each part of your answer.</p>`;const math=!!st.math;return `<p class="bbDirLead"><b>Read the directions carefully before you begin.</b></p><p>This module has ${st.count||questionCount(st)} questions. You may move back and forth among questions in this module until time expires.</p><p>${math?'A calculator and the built-in reference sheet are available for permitted questions.':'Use the annotation tools to highlight or make notes while you work.'}</p><p>You can mark questions for review and return to them from the question menu. Once you leave this module, you cannot return to it.</p>`}
function bbDirections(idx){stopTimer();const st=session.base.steps[idx];if(!st){finishExam();return}session.stepIndex=idx;app.innerHTML=`<div class="bbDirectionsFull"><main class="bbDirPage"><h1>${escapeHtml(st.label.replace(/:\s*.+$/,''))} Directions</h1><div class="bbDirCopy">${bbDirectionCopy(st)}</div></main><footer><div class="bbDirName">${escapeHtml(bbCandidateName())}</div><button class="bbYellow" id="continue">${session.exam==='AP'?'Resume Testing':'Begin'}</button></footer></div>`;$('#continue').onclick=()=>beginStep(idx)}
function beginStep(idx){const prev=session?.base?.steps?.[session.stepIndex]||null,step=session.base.steps[idx];session.stepIndex=idx;session.qIndex=0;if(!step){finishExam();return}if(step.type==='break'){renderBreak();return}if(session.exam==='TOEFL'&&step.type==='toefl-speaking'){stopTimer();session.seconds=0;renderQuestion();return}if(session.exam==='TOEFL'&&step.type==='toefl-writing'){stopTimer();session.seconds=0;session.tfWritingTimerMode=null;renderQuestion();return}const sameToeflSection=session.exam==='TOEFL'&&prev&&prev!==step&&prev.label===step.label&&prev.type===step.type&&session.seconds>0;if(!sameToeflSection)session.seconds=bbStepDuration(step);if(!session.annotations)session.annotations={};if(!session.scrollStates)session.scrollStates={};if(!session.eliminated)session.eliminated={};if(session.seconds>0)startTimer();else stopTimer();renderQuestion()}
function nextStep(){stopTimer();const ni=session.stepIndex+1;if(ni>=session.base.steps.length){finishExam();return}const n=session.base.steps[ni];if(session.exam==='SAT'||session.exam==='AP'){if(n.type==='break'){session.stepIndex=ni;session.seconds=bbStepDuration(n);renderBreak()}else bbDirections(ni);return}if(n.type==='break'){session.stepIndex=ni;session.seconds=bbStepDuration(n);renderBreak()}else if(session.exam==='TOEFL'){const p=session.base.steps[session.stepIndex];if(p&&p.label===n.label&&p.type===n.type)beginStep(ni);else tfSectionIntro(ni)}else if(session.exam==='ACT')actSectionIntro(ni);else beginStep(ni)}
function bbAfterBreak(){stopTimer();const ni=session.stepIndex+1;if(ni>=session.base.steps.length){finishExam();return}bbDirections(ni)}
function bbSkipConfirm(done){showModal('Skip break?',`<p>Are you sure you want to skip your break?</p><div class="bbConfirmRow"><button class="bbConfirmCancel" data-close>Cancel</button><button class="bbConfirmPrimary" id="confirmSkip">Skip Break</button></div>`);$('#confirmSkip').onclick=()=>{closeModal();done()}}
function renderBreak(){stopTimer();const step=session.base.steps[session.stepIndex];session.breakEnd??=Date.now()+(bbStepDuration(step)||600)*1000;let sec=Math.max(0,Math.ceil((session.breakEnd-Date.now())/1000));app.innerHTML=`<div class="bbBreakV11"><div class="bbBreakLeftV11"><div class="bbBreakTimerBox"><div>Remaining Break Time:</div><strong id="breakTime">${formatTime(sec)}</strong></div><button class="bbBreakResume" id="resume" disabled>Resume Testing</button><button class="bbSkipBreak" id="skipBreak">Skip Break</button><div class="bbStudent breakname">${escapeHtml(bbCandidateName())}</div></div><div class="bbBreakRightV11"><h2>Break</h2><p class="bbBreakIntro">You can continue when the break ends, or choose <b>Skip Break</b> when you're ready to move on.</p><hr><h1>Take a Break: Do Not Close<br>Your Device</h1><p>Place your exam materials on your desk now.</p><h3>Follow these rules during the break:</h3><ol><li>Do not disturb students who are still testing.</li><li>Do not exit the app or close your laptop.</li><li>Do not access phones, smartwatches, textbooks, notes, or the internet.</li><li>Do not eat or drink in the test room.</li><li>Do not discuss the exam with anyone.</li></ol></div></div>`;const btn=$('#resume'),skip=$('#skipBreak');let ended=false,id=null;const go=()=>{if(ended)return;ended=true;if(id)clearInterval(id);session.breakEnd=null;bbAfterBreak()};id=setInterval(()=>{sec=Math.max(0,Math.ceil((session.breakEnd-Date.now())/1000));const x=$('#breakTime');if(x)x.textContent=formatTime(sec);if(sec===0){clearInterval(id);btn.disabled=false;btn.classList.add('ready');setTimeout(go,650)}},1000);btn.onclick=()=>{if(!btn.disabled)go()};skip.onclick=()=>bbSkipConfirm(go)}
function bbConfetti(){return Array.from({length:86},(_,i)=>{const x=(i*37)%101,d=(i%17)*-.13,t=2.8+(i%9)*.17,r=(i*53)%360,y=(i*61)%94;return `<i class="bbConfettiPiece c${i%5}" style="--x:${x}vw;--d:${d}s;--t:${t}s;--r:${r}deg;--y:${y}vh;top:${y}vh"></i>`}).join('')}
function bbLaptopArt(){return `<svg viewBox="0 0 300 190" aria-hidden="true"><ellipse cx="150" cy="98" rx="82" ry="73" fill="#eef5ff"/><path d="M83 48h134a10 10 0 0 1 10 10v78H73V58a10 10 0 0 1 10-10Z" fill="#e9eef7" stroke="#333" stroke-width="4"/><rect x="91" y="65" width="118" height="66" fill="#fff" stroke="#333" stroke-width="4"/><circle cx="150" cy="99" r="29" fill="#dff7ff" stroke="#333" stroke-width="4"/><path d="M137 94c0-5 7-5 7 0m12 0c0-5 7-5 7 0m-26 13c8 14 22 14 30 0" fill="none" stroke="#333" stroke-width="4" stroke-linecap="round"/><path d="M59 138h182v11c0 8-9 14-19 14H78c-10 0-19-6-19-14v-11Z" fill="#dfe5f1" stroke="#333" stroke-width="4"/></svg>`}
function finishExam(){stopTimer();if(session.exam==='ACT'){app.innerHTML=`<div class="act" style="background:#f7f7f7;align-items:center;justify-content:center"><div style="width:620px;background:white;border:1px solid #bbb;padding:42px;text-align:center"><div class="actWord" style="color:#003c69;margin:0 0 25px">ACT</div><h1>Test Complete</h1><p>Your responses have been saved in this simulator.</p><button class="actNavBtn" style="background:#003c69" id="doneHome">Return to Home</button></div></div>`}else if(session.exam==='TOEFL'){app.innerHTML=`<div class="tfIntro"><div class="tfIntroTop"></div><div class="tfIntroCard" style="text-align:center"><h1>Your test is complete.</h1><p>Your responses have been saved.</p><button class="tfBtn primary" id="doneHome">Exit</button></div></div>`}else{app.innerHTML=`<div class="bbFinishV11"><div class="bbConfetti" aria-hidden="true">${bbConfetti()}</div><button class="bbFinishHomeTop" id="doneHomeTop">Return to Home <span class="bbHomeGlyph">${bbMiniIcon('home')}</span></button><h1>You're All Finished!</h1><div class="bbFinishCard">${bbLaptopArt()}<p>Your answers have been submitted.</p><p>When you see this page on test day, you'll know<br>your test has been completed.</p><button class="bbYellow" id="doneHome">Return to Home</button></div></div>`}$('#doneHome').onclick=home;if($('#doneHomeTop'))$('#doneHomeTop').onclick=home}
function renderQuestion(){const step=session.base.steps[session.stepIndex];if(step.type.startsWith('bluebook'))renderBluebook(step);else if(step.type==='ap-writing')renderAPWriting(step);else if(step.type.startsWith('act'))renderACT(step);else if(step.type.startsWith('toefl'))renderTOEFL(step)}
function routeAccuracy(sectionId){const p=session.base.package,qs=p?.sections?.[sectionId]?.questions||[];if(!qs.length)return 1;let scored=0,correct=0;for(let i=0;i<qs.length;i++){const q=qs[i],a=session.answers[sectionId+':'+i];if(q.correct===undefined||a===undefined)continue;scored++;if(a===q.correct)correct++}return scored?correct/scored:0}
function resolvedSectionId(step){const p=session.base.package;if(!p?.sections)return step.id;const pairs={rw2:['rw1','rw2_easy','rw2_hard'],reading2:['reading1','reading2_easy','reading2_hard'],listening2:['listening1','listening2_easy','listening2_hard'],math2:['math1','math2_easy','math2_hard']};const pair=pairs[step.id];if(pair&&p.sections[pair[1]]&&p.sections[pair[2]]){if(!session.routes[step.id]){const th=Number(p.manifest?.routingThreshold??0.6);session.routes[step.id]=routeAccuracy(pair[0])>=th?'hard':'easy'}return session.routes[step.id]==='hard'?pair[2]:pair[1]}return step.id}
function questionsFor(step){const p=session.base.package,id=resolvedSectionId(step);if(p?.sections?.[id]?.questions?.length)return p.sections[id].questions;if(p?.sections?.[step.id]?.questions?.length)return p.sections[step.id].questions;const d=demoQuestions[session.exam]||[];if(Array.isArray(d))return d;return d[step.id]||d[step.label?.toLowerCase()]||[]}
function questionCount(step){const qs=questionsFor(step);if(session.exam==='TOEFL'&&!session.base.package&&qs.length)return qs.length;return session.base.package&&qs.length?qs.length:(step.count||qs.length||1)}
function qCurrent(step){const qs=questionsFor(step);return qs[session.qIndex%Math.max(1,qs.length)]||{id:'blank',type:'mcq',prompt:'Question content not provided.',choices:['A','B','C','D']}}
function bbScrollKey(step){return step.id+':'+session.qIndex}
function bbSaveScroll(step){if(!session.scrollStates)session.scrollStates={};const k=bbScrollKey(step),p=$('.bbPassage.exact'),q=$('.bbQuestion.exact');session.scrollStates[k]={p:p?.scrollTop||0,q:q?.scrollTop||0}}
function bbRestoreScroll(step){const v=session.scrollStates?.[bbScrollKey(step)];if(!v)return;requestAnimationFrame(()=>{const p=$('.bbPassage.exact'),q=$('.bbQuestion.exact');if(p)p.scrollTop=v.p||0;if(q)q.scrollTop=v.q||0})}
function bbAnnotatedParagraphs(text,key){let html=escapeHtml(text||'');for(const a of (session.annotations?.[key]||[])){const t=escapeHtml(a.text||'');if(!t)continue;const cls=a.underline?'bbAnnUnderline':'bbAnnHighlight';html=html.replace(t,`<mark class="${cls}">${t}</mark>`)}return html.split(/\n\n+/).map(p=>`<p>${p}</p>`).join('')}
function bbOpenAnnotation(key){const sel=(session.bbSelection||window.getSelection()?.toString()||'').trim(),saved=session.annotations?.[key]||[];document.querySelector('.bbAnnotDrawer')?.remove();const d=el('div','bbAnnotDrawer');d.innerHTML=`<div class="bbAnnotHead"><b>${sel?`New Annotation: “${escapeHtml(sel.slice(0,90))}${sel.length>90?'…':''}”`:'Highlights & Notes'}</b><button id="bbAnnotClose">CLOSE&nbsp; ×</button></div><div class="bbAnnotTools"><span>Highlight Color:</span><button class="bbColorDot" aria-label="Yellow highlight"></button><span>Underline style:</span><button class="bbUnderlineBtn" id="bbUnderline"><u>U</u></button></div><textarea id="bbNote" placeholder="${sel?'Add a note (optional)':'Select text in the passage, then open Annotate to create a highlight or note.'}"></textarea><div class="bbAnnotActions"><button id="bbAnnotSave" ${sel?'':'disabled'}>Save</button><button id="bbAnnotCancel">Cancel</button>${saved.length?`<span class="bbSavedCount">${saved.length} saved annotation${saved.length===1?'':'s'}</span>`:''}</div>`;document.body.appendChild(d);let underline=false;$('#bbUnderline').onclick=()=>{$('#bbUnderline').classList.toggle('on');underline=!underline};const close=()=>d.remove();$('#bbAnnotClose').onclick=close;$('#bbAnnotCancel').onclick=close;$('#bbAnnotSave').onclick=()=>{if(!sel)return;if(!session.annotations)session.annotations={};(session.annotations[key]??=[]).push({text:sel,note:$('#bbNote').value,underline});session.bbSelection='';close();renderQuestion()}}
function bbDirectionsPopup(step){showModal('Directions',bbDirectionCopy(step))}
function bbBattery(){const box=$('#bbBattery');if(!box||!navigator.getBattery)return;navigator.getBattery().then(b=>{const u=()=>box.textContent=Math.round(b.level*100)+'%';u();b.addEventListener('levelchange',u)}).catch(()=>{})}
function renderBluebook(step){const q=qCurrent(step),key=step.id+':'+session.qIndex,ans=session.answers[key],split=!!q.passage,math=!!step.math,elim=session.eliminated?.[key]||[];const tools=math?`<button class="bbIconTool" id="calcBtn">${bbIcon('calc')}<span>Calculator</span></button><button class="bbIconTool" id="refBtn">${bbIcon('ref')}<span>Reference</span></button>`:`<button class="bbIconTool" id="annotateBtn">${bbIcon('pen')}<span>Annotate</span></button>`;app.innerHTML=`<div class="bb bbExact bbV11"><div class="bbHeader exact"><div class="bbHeadLeft"><div class="bbSec">${escapeHtml(step.label)}</div><button class="bbDirectionsLink" id="directionsBtn">Directions <span>${bbMiniIcon('down')}</span></button></div><div class="bbTimer"><span id="timerText">${hiddenTimer?'••:••':formatTime(session.seconds)}</span><button id="hideTimer">${hiddenTimer?'Show':'Hide'}</button></div><div class="bbTools">${tools}<button class="bbIconTool" id="moreBtn">${bbIcon('more')}<span>More</span></button><span class="bbBattery" id="bbBattery"></span></div></div><div class="bbRail"></div><div class="bbBody exact ${split?'split':''}">${split?`<article class="bbPassage exact"><div class="bbPaneFloat">${bbMiniIcon('expand')}</div><div class="bbPassageText">${bbAnnotatedParagraphs(q.passage,key)}</div></article>`:''}<section class="bbQuestion exact ${split?'':'single'}"><div class="bbPaneFloat right">${bbMiniIcon('expand')}</div><div class="bbQTop"><span class="bbQBadge">${session.qIndex+1}</span><button class="bbMark" id="markBtn"><span class="bookmark ${session.flags[key]?'on':''}"></span>${session.flags[key]?'Marked for Review':'Mark for Review'}</button><button class="bbElim ${session.elimMode?'on':''}" id="elimBtn" title="Option Eliminator">ABC̶</button></div><div class="qPrompt bbPrompt">${escapeHtml(q.prompt||'')}</div>${mediaHTML(q)}${renderBluebookAnswer(q,ans,key)}</section></div><div class="bbRail bottom"></div><div class="bbTestFooter"><div class="bbStudent">${escapeHtml(bbCandidateName())}</div><div class="bbFooterCenter"><button class="bbQuestionMenu" id="menuBtn">Question ${session.qIndex+1} of ${questionCount(step)} <span>${bbMiniIcon('up')}</span></button></div><div class="bbFooterNav"><button class="bbBack" id="backBtn">Back</button><button class="bbNext" id="nextBtn">Next</button></div></div></div>`;wireAnswer(q,key);document.querySelectorAll('.bbChoice').forEach(b=>{const i=+b.dataset.choice;b.classList.toggle('eliminated',elim.includes(i));b.onclick=e=>{if(e.target.closest('.bbCross'))return;bbSaveScroll(step);session.answers[key]=i;renderQuestion()};const x=b.querySelector('.bbCross');if(x)x.onclick=e=>{e.stopPropagation();const a=session.eliminated[key]??=[];const n=+x.dataset.elim,pos=a.indexOf(n);pos>=0?a.splice(pos,1):a.push(n);session.eliminated[key]=a;b.classList.toggle('eliminated',a.includes(n))}});$('#backBtn').onclick=()=>{if(session.qIndex>0){bbSaveScroll(step);session.qIndex--;renderQuestion()}};$('#nextBtn').onclick=()=>{bbSaveScroll(step);nextQ()};$('#menuBtn').onclick=()=>{bbSaveScroll(step);bbReviewPage(step)};$('#markBtn').onclick=()=>{bbSaveScroll(step);session.flags[key]=!session.flags[key];renderQuestion()};$('#hideTimer').onclick=toggleTimer;$('#directionsBtn').onclick=()=>bbDirectionsPopup(step);if(math){$('#calcBtn').onclick=calculatorModal;$('#refBtn').onclick=referenceModal}else{const a=$('#annotateBtn');a.onmousedown=()=>session.bbSelection=window.getSelection()?.toString()||'';a.onclick=()=>bbOpenAnnotation(key)}$('#elimBtn').onclick=()=>{$('#elimBtn').classList.toggle('on');session.elimMode=!session.elimMode};$('#moreBtn').onclick=helpModal;bbBattery();bbRestoreScroll(step)}
function renderBluebookAnswer(q,ans,key){if(q.type==='numeric')return `<div class="bbSpr"><label>Enter your answer</label><input id="numericAnswer" value="${escapeHtml(ans??'')}"></div>`;const choices=q.choices||['Choice A','Choice B','Choice C','Choice D'];return `<div class="bbChoices">${choices.map((c,i)=>`<button class="bbChoice ${ans===i?'selected':''}" data-choice="${i}"><span class="bbLetter">${String.fromCharCode(65+i)}</span><span class="bbChoiceText">${escapeHtml(c)}</span><span class="bbCross" data-elim="${i}" title="Eliminate answer">A̶</span></button>`).join('')}</div>`}
function renderAPWriting(step){const q=qCurrent(step),key=step.id+':'+session.qIndex;const sectionNo=/II|2/.test(step.label)?2:1;app.innerHTML=`<div class="bb bbExact"><div class="bbHeader exact"><div class="bbHeadLeft"><div class="bbSec">${escapeHtml(step.label)}</div><button class="bbDirectionsLink">Directions ${bbMiniIcon('down')}</button></div><div class="bbTimer"><span id="timerText">${hiddenTimer?'--:--':formatTime(session.seconds)}</span><button id="hideTimer">${hiddenTimer?'Show':'Hide'}</button></div><div class="bbTools"><button class="bbIconTool" id="moreBtn">•••<span>More</span></button></div></div><div class="bbRail"></div><div class="bbBody exact split apFrqBody"><article class="bbPassage exact apSources"><div class="bbPassageText"><h3>Source Material</h3>${paragraphs(q.passage||'Source material will appear here.')}${mediaHTML(q)}</div></article><section class="bbQuestion exact apFrq"><div class="bbQTop"><span class="bbQBadge">${session.qIndex+1}</span><button class="bbMark" id="markBtn"><span class="bookmark ${session.flags[key]?'on':''}"></span>${session.flags[key]?'Marked for Review':'Mark for Review'}</button></div><div class="qPrompt bbPrompt">${escapeHtml(q.prompt||'Free-response prompt')}</div><textarea id="frq" class="bbEssay" spellcheck="false" aria-label="Free response">${escapeHtml(session.answers[key]||'')}</textarea><div class="bbEssayCount" id="essayCount"></div></section></div><div class="bbRail bottom"></div><div class="bbTestFooter"><div class="bbStudent">Test Taker</div><div class="bbFooterCenter"><button class="bbQuestionMenu" id="menuBtn">Question ${session.qIndex+1} of ${questionCount(step)} ${bbMiniIcon('up')}</button></div><div class="bbFooterNav"><button class="bbBack" id="backBtn">Back</button><button class="bbNext" id="nextBtn">Next</button></div></div></div>`;const ta=$('#frq'),upd=()=>{session.answers[key]=ta.value;const c=$('#essayCount');if(c)c.textContent=(ta.value.trim()?ta.value.trim().split(/\s+/).length:0)+' words'};ta.oninput=upd;upd();$('#backBtn').onclick=prevQ;$('#nextBtn').onclick=nextQ;$('#menuBtn').onclick=()=>questionMenu(step,'bb');$('#markBtn').onclick=()=>{session.flags[key]=!session.flags[key];renderQuestion()};$('#hideTimer').onclick=toggleTimer;$('#moreBtn').onclick=helpModal}
function actWelcome(){app.innerHTML=`<div class="actGatewayLogin"><div class="gatewayBackdrop"></div><div class="gatewayCard"><div class="gatewayLogo">ACT</div><h1>Welcome to ACT Gateway</h1><label>Email</label><input class="gatewayInput" value="student@example.com" aria-label="Email"><label>Password <span>Sign in another way</span></label><div class="gatewayPass"><input class="gatewayInput" type="password" value="simulator"><button>◉</button></div><p class="gatewayTerms">By signing in, you are agreeing to the ACT Gateway Terms of Use.</p><button class="gatewaySign" id="actSign">Sign In</button><button class="gatewayStaff">I’m a member of the testing staff</button></div><div class="gatewayFooter">ACT Gateway Terms of Use &nbsp;&nbsp; ACT Privacy Policy</div></div>`;$('#actSign').onclick=actDashboard}
function actDashboard(){app.innerHTML=`<div class="gatewayDash"><div class="gatewayDashTop"><strong>The ACT® Test</strong><button class="bbPlain" id="exitHome">Sign Out</button></div><div class="gatewayDashBody"><aside><div class="gatewayDate">Upcoming Test</div><div class="gatewayDateBig">Online ACT</div><div class="gatewayReadyDot">● Device readiness complete</div><button class="gatewayDevice">▣ &nbsp; Run Device Check</button></aside><main><h2>Your Test</h2><div class="gatewayTestCard"><div><strong>${escapeHtml(session.base.title)}</strong><div class="small">Testing application ready</div></div><button class="gatewayBegin" id="actStart">Begin Test</button></div><h2>Take a Practice Test</h2><div class="gatewayInfoCard">On test day, your test will be delivered through the online testing platform. Take a practice test and become familiar with the application before test day.</div></main></div></div>`;$('#actStart').onclick=()=>actSectionIntro(0);$('#exitHome').onclick=home}
function actSectionIntro(idx){const step=session.base.steps[idx];session.stepIndex=idx;app.innerHTML=`<div class="act"><div class="actTop exact"><div class="actWord">ACT</div><div class="actSpacer"></div><div class="actTopBtn timerField">TOTAL TIME LEFT&nbsp; ${formatTime(step.duration||0,true)}</div></div><div class="actInfoWrap"><div class="actCounter">1 of ${Math.max(3,questionCount(step)+2)}</div><h1>${escapeHtml(step.label)} Test Directions</h1><p>The next screen in this section contains instructions about the ${escapeHtml(step.label)} test.</p><div class="actInstructionPanel"><h2>${escapeHtml(step.label)} Test</h2><p>You will have <b>${Math.round((step.duration||0)/60)} minutes</b> to complete this test section.</p><p>Use the navigation controls to move between questions. You may flag items and use the INDEX panel to return to questions in this section.</p></div></div><div class="actBottom exact"><button class="actIndexBtn" id="helpBtn">▣ &nbsp; HELP SCREEN</button><div></div><button class="actPrevNext" disabled>‹ PREV</button><div class="actCount">1 of ${Math.max(3,questionCount(step)+2)}</div><button class="actPrevNext" id="actContinue">NEXT ›</button></div></div>`;$('#actContinue').onclick=()=>beginStep(idx);$('#helpBtn').onclick=helpModal}
function renderACT(step){const q=qCurrent(step),key=step.id+':'+session.qIndex,ans=session.answers[key];if(step.type==='act-writing'){renderACTWriting(step,q,key);return}const split=!!q.passage||step.passage;app.innerHTML=`<div class="act ${document.body.classList.contains('highContrast')?'highContrast':''}"><div class="actTop exact"><div class="actWord">ACT</div><button class="actToolTop" id="toolsBtn">⚒ TOOLS⌄</button><button class="actToolTop" id="contrastBtn">▰ CONTRAST⌄</button><div class="actSpacer"></div><div class="actField">▰ ANSWERED&nbsp;&nbsp; ${answeredCount(step)} OF ${questionCount(step)}</div><button class="actField timer" id="actTimer">TOTAL TIME LEFT&nbsp; ◉ &nbsp;${hiddenTimer?'••:••:••':formatTime(session.seconds,true)}</button><button class="actEnd exact" id="endSection">▰ END TEST</button></div><div class="actMain exact">${split?`<article class="actPass ${toolClass()}">${paragraphs(q.passage||'Passage content will appear here.')}</article>`:''}<section class="actQuestion exact"><div class="actItemCounter">${session.qIndex+3} of ${questionCount(step)+2}</div><button class="actFlag exact" id="flagBtn"><span class="actBookmark ${session.flags[key]?'on':''}"></span>${session.flags[key]?'FLAGGED':'FLAG'}</button><div class="qPrompt actPrompt">${escapeHtml(q.prompt||'')}</div>${mediaHTML(q)}<div class="actChoices exact">${renderACTAnswer(q,ans,key)}</div></section></div><div class="actBottom exact"><button class="actIndexBtn" id="indexBtn">☰ &nbsp; INDEX</button><button class="actIndexBtn" id="helpBtn">▣ &nbsp; HELP SCREEN</button><button class="actPrevNext" id="prevBtn">‹ PREV</button><div class="actCount">${session.qIndex+3} of ${questionCount(step)+2}</div><button class="actPrevNext" id="nextBtn">NEXT ›</button></div></div>`;wireAnswer(q,key);$('#toolsBtn').onclick=()=>actDropdown('tools');$('#contrastBtn').onclick=()=>actDropdown('contrast');$('#actTimer').onclick=()=>{hiddenTimer=!hiddenTimer;renderQuestion()};$('#flagBtn').onclick=()=>{session.flags[key]=!session.flags[key];renderQuestion()};$('#indexBtn').onclick=()=>questionMenu(step,'act');$('#helpBtn').onclick=helpModal;$('#prevBtn').onclick=prevQ;$('#nextBtn').onclick=nextQ;$('#endSection').onclick=endSectionConfirm}
function renderACTAnswer(q,ans,key){const choices=q.choices||['NO CHANGE','Choice B','Choice C','Choice D'];return `<div class="actAnswerList">${choices.map((c,i)=>`<button class="actAnswer ${ans===i?'selected':''}" data-choice="${i}"><span class="actRadio"></span><b>${String.fromCharCode(65+i)}.</b><span>${escapeHtml(c)}</span></button>`).join('')}</div>`}
