  const next=()=>{if(i>=list.length){onend&&onend();return}const t=list[i++],hint=/male|man|m\b/i.test(String(t.speaker||t.voice||''))?'male':'female',src=assetURL(t.audio||'');if(src){const a=new Audio(src);session.tfPromptAudio=a;a.volume=Math.max(.05,Math.min(1,Number(session?.tfVolume??.72)));a.onended=()=>{session.tfPromptAudio=null;setTimeout(next,110)};a.onerror=()=>tfSpeakText(String(t.text||''),()=>setTimeout(next,110),hint);a.play().catch(()=>tfSpeakText(String(t.text||''),()=>setTimeout(next,110),hint));return}tfSpeakText(String(t.text||''),()=>setTimeout(next,110),hint)};
