function tfMicrophoneCheck(){const body=`<section class="tfRefPanel mic"><h1>Adjusting the Microphone</h1><div class="tfThinRule"></div><p>In order to check your <b>microphone volume</b>, you will speak into the microphone using your normal tone and volume. For best recording results, your voice level should remain generally within the Good Range. While you speak the microphone will adjust automatically.</p><p class="tfExampleLabel"><b>Example:</b></p><div class="tfMicExamples">${tfMicExampleBars('good')}${tfMicExampleBars('loud')}</div></section>`;tfRefShell({section:'Reading',actions:tfVolumeButton(),body});$('#volumeBtn').onclick=tfToggleVolumeControl;tfFixedNarration('microphoneCheck','Adjusting the microphone. In order to check your microphone volume, you will speak into the microphone using your normal tone and volume. For best recording results, your voice level should remain generally within the Good Range. While you speak, the microphone will adjust automatically.',520,()=>setTimeout(()=>{if(session?.exam==='TOEFL')tfOpenMicRecord()},420))}
function tfOpenMicRecord(){if($('#tfMicOverlay'))return;const overlay=el('div','tfMicOverlay');overlay.id='tfMicOverlay';overlay.innerHTML=`<div class="tfMicDialog"><button class="tfRecordCircle" id="beginMic"><span class="tfRecordMic">${tfSvgIcon('mic')}</span><strong id="recordLabel">RECORD</strong></button><div class="tfMicDialogCopy"><p>Select the 'Record' button. A timer will count down until the system is ready to record.</p><p>To check your microphone level, you will record the following paragraph using your normal tone and volume.</p><p>There are several reasons why I would prefer to live in a large city. Some of the greatest advantages would include the number of job opportunities and career options, public transportation, greater diversity, and a wealth of entertainment. Also, large cities typically have a great deal to offer in terms of history, art and culture.</p><div class="tfLiveMeter"><div class="tfLiveBars" id="tfMeter">${Array.from({length:15},()=>'<span></span>').join('')}</div><div class="tfLiveZones"><span>Too<br>Quiet</span><span>Good</span><span>Too Loud</span></div></div><div class="tfMicResult" id="tfMicResult"></div></div></div>`;document.querySelector('.tfReference').appendChild(overlay);$('#beginMic').onclick=runTfMic;tfFixedNarration('microphoneRecord','Select the Record button. A timer will count down until the system is ready to record. To check your microphone level, you will record the following paragraph using your normal tone and volume.',360)}
async function runTfMic(){const btn=$('#beginMic'),label=$('#recordLabel'),result=$('#tfMicResult');if(!btn)return;btn.disabled=true;result.textContent='';try{const stream=await navigator.mediaDevices.getUserMedia({audio:true}),C=window.AudioContext||window.webkitAudioContext,ctx=new C(),src=ctx.createMediaStreamSource(stream),an=ctx.createAnalyser();an.fftSize=256;src.connect(an);const data=new Uint8Array(an.frequencyBinCount),bars=[...document.querySelectorAll('#tfMeter span')];let raf,peak=0;for(let n=3;n>0;n--){label.textContent=String(n);await new Promise(r=>setTimeout(r,700))}label.textContent='RECORDING';const draw=()=>{an.getByteFrequencyData(data);const avg=data.reduce((a,b)=>a+b,0)/data.length;peak=Math.max(peak,avg);const n=Math.max(1,Math.min(bars.length,Math.round(avg/10)));bars.forEach((b,i)=>b.classList.toggle('on',i<n));raf=requestAnimationFrame(draw)};draw();await new Promise(r=>setTimeout(r,4800));cancelAnimationFrame(raf);stream.getTracks().forEach(t=>t.stop());ctx.close();const ok=peak>=5;bars.forEach((b,i)=>b.classList.toggle('on',ok&&i<8));if(ok){label.textContent='GOOD';result.innerHTML='<span class="tfGoodTiny">✓</span> Microphone level is in the Good Range.';setTimeout(()=>tfSectionIntro(0),850)}else{label.textContent='RECORD';result.textContent='Microphone level was too quiet. Select Record and try again.';btn.disabled=false}}catch(e){label.textContent='RECORD';result.textContent='Microphone access is required. Check Windows microphone permissions and try again.';btn.disabled=false}}
function tfToggleVolumeControl(){const old=$('#tfVolumePopover'),vb=$('#volumeBtn');if(old){old.remove();vb?.classList.remove('open');return}const pop=el('div','tfVolumePopover');pop.id='tfVolumePopover';const level=Math.round(Number(session?.tfVolume??.72)*100);pop.innerHTML=`<button class="tfVolumeClose" id="tfVolumeClose" aria-label="Close volume control">${tfIcon('close')}</button><div class="tfVolumeBars" id="tfVolumeBars">${Array.from({length:17},(_,i)=>`<span style="--i:${i}"></span>`).join('')}</div><input class="tfVolumeRange" id="tfVolumeRange" type="range" min="0" max="100" value="${level}" aria-label="Volume">`;const root=document.querySelector('.tfReference');root.appendChild(pop);if(vb){vb.classList.add('open');const br=vb.getBoundingClientRect(),rr=root.getBoundingClientRect();pop.style.left=Math.max(8,br.left-rr.left-145)+'px';pop.style.right='auto'}const r=$('#tfVolumeRange'),bars=[...document.querySelectorAll('#tfVolumeBars span')],paint=()=>{const n=Math.round((+r.value/100)*bars.length);bars.forEach((b,i)=>b.classList.toggle('active',i<n));session.tfVolume=+r.value/100};paint();r.oninput=()=>{paint();tfTone(560+Number(r.value)*2,.045,.025)};$('#tfVolumeClose').onclick=()=>{pop.remove();vb?.classList.remove('open')};tfTone(720,.085,.035)}
