function tfSectionIntro(idx){session.stepIndex=idx;const step=session.base.steps[idx],kind=step.type.replace('toefl-','');let copy='',rows=[],color='';if(kind==='reading'){copy=`In this session, you will work through ${questionCount(step)} reading task pages to demonstrate how well you understand academic and non-academic texts in English. The imported package determines the number of tasks in this session. There are three types of tasks in the reading section of the test.`;rows=[['Complete the Words','Fill in the missing letters in a paragraph.'],['Read in Daily Life','Answer questions about everyday reading material.'],['Read an Academic Passage','Answer questions about academic passages.']];color='reading'}else if(kind==='listening'){copy=`In this session, you will answer ${questionCount(step)} questions to demonstrate how well you understand spoken English. The imported package determines the number of tasks in this session. There are three types of tasks in the listening section of the test.`;rows=[['Listen and Choose a Response','Select the best response to the question or statement.'],['Conversations','Answer questions about short conversations.'],['Announcements and Academic Talks','Answer questions about announcements and academic talks.']];color='listening'}else if(kind==='writing'){copy=`In this session, you will answer ${questionCount(step)} questions to demonstrate how well you can write in English. The imported package determines the tasks in this session. Your responses will be saved. Feedback and explanations are available after the test. There are three types of tasks in the writing section of the test.`;rows=[['Build a Sentence','Create a grammatical sentence.'],['Write an Email','Write an email using information provided.'],['Write for an Academic Discussion','Participate in an online discussion.']];color='writing'}else{copy=`In this session, you will answer ${questionCount(step)} questions to demonstrate how well you can speak English. There are two types of tasks.`;rows=[['Listen and Repeat','Listen and repeat what you heard'],['Take an Interview','Answer questions from the interviewer']];color='speaking'}const table=`<table class="tfTaskTable ${color}"><thead><tr><th>Type of Task</th><th>Description</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHtml(r[0])}</td><td>${escapeHtml(r[1])}</td></tr>`).join('')}</tbody></table>`;const extra=kind==='listening'?'<p class="tfNoReturn">You WILL NOT be able to return to previous questions.</p>':'';const body=`<section class="tfRefPanel sectionIntro"><h1>${escapeHtml(step.label)} Section</h1><div class="tfThinRule"></div><p>${copy}</p>${table}${extra}</section>`;const isWriting=kind==='writing',actions=isWriting?tfActionButton('tfBegin','Continue'):tfVolumeButton()+tfActionButton('tfBegin','Begin');tfRefShell({section:step.label,actions,body});if($('#volumeBtn'))$('#volumeBtn').onclick=tfToggleVolumeControl;$('#tfBegin').onclick=()=>beginStep(idx);const spokenRows=rows.map(r=>r[0]+'. '+r[1]).join(' ');tfFixedNarration(kind+'SectionIntro',step.label+' Section. '+copy+' '+spokenRows+(kind==='listening'?' You will not be able to return to previous questions.':''),520)}
