  if(step.type==='toefl-writing'){renderTFWriting(step,q,key);return}
  if(step.type==='toefl-speaking'){renderTFSpeaking(step,q,key);return}
  const ans=session.answers[key],fill=q.type==='fill_letters',daily=['daily_life','notice','read_notice'].includes(q.type),title=q.title||q.passageTitle||'Reading Passage';
  const actions=tfVolumeButton()+(session.qIndex>0?tfActionButton('tfBack','Back','ghost','left'):'')+tfActionButton('tfNext','Next'),meta=tfQuestionMeta(step,q),right=tfSectionTimerRight();
  let body;
  if(fill)body=`<section class="tfFillScreen"><h1>${escapeHtml(q.prompt||'Fill in the missing letters in the paragraph.')}</h1><div class="tfFillBlock">${renderTFFillLetters(q,ans,key)}</div></section>`;
