function tfWritingTimeRemaining(){const step=session.base.steps[session.stepIndex],b=tfWritingBand(step,tfWritingMode(qCurrent(step))),body=`<section class="tfRefPanel timeRemaining"><h1>Time Remaining</h1><div class="tfThinRule"></div><p>You still have time to respond. As long as there is time remaining, you can keep writing or revise your response.</p><p>Select <b>Back</b> to keep writing or revising.</p><p>Select <b>Continue</b> to leave this question.</p><p>Once you leave this question, you WILL NOT be able to return to it.</p></section>`;tfRefShell({section:'Writing',meta:b.meta,right:b.right,actions:tfActionButton('tfReturn','Back','ghost','left')+tfActionButton('tfLeave','Continue'),body,question:true});$('#tfReturn').onclick=renderQuestion;$('#tfLeave').onclick=advanceAfterWriting;$('#hideTimer').onclick=toggleTimer;tfFixedNarration('writingTimeRemaining','Time Remaining. You still have time to respond. As long as there is time remaining, you can keep writing or revise your response. Select Back to keep writing or revising. Select Continue to leave this question. Once you leave this question, you will not be able to return to it.',420)}
