  const renderTokens=()=>{const sel=$('#selectedWords'),bank=$('#wordBank');sel.innerHTML=Array.from({length:slots},(_,i)=>`<button class="tfSentenceSlot ${arr[i]?'filled':''}" data-remove="${i}" ${arr[i]?'':'disabled'}>${escapeHtml(arr[i]||'')}</button>`).join('');bank.innerHTML=remaining().map(({w,i})=>`<button class="tfWordToken official" data-word-index="${i}">${escapeHtml(w)}</button>`).join('');document.querySelectorAll('[data-word-index]').forEach(bu=>bu.onclick=()=>{if(arr.length>=slots)return;arr=[...arr,words[+bu.dataset.wordIndex]];session.answers[key]=arr;renderTokens()});document.querySelectorAll('[data-remove]').forEach(bu=>bu.onclick=()=>{const i=+bu.dataset.remove;if(Number.isFinite(i)&&arr[i]){arr.splice(i,1);session.answers[key]=[...arr];renderTokens()}})};renderTokens();$('#tfNext').onclick=nextQ;$('#hideTimer').onclick=toggleTimer
