function tfSpeakingTaskIntro(repeat,step,q,key){const mode=repeat?'repeat':'interview',introKey='speaking:'+mode;session.tfTaskIntros=session.tfTaskIntros||{};session.tfTaskIntros[introKey]=true;const title=repeat?'Listen and Repeat':'Take an Interview',copy=repeat?`<p>You will listen as someone speaks to you. Listen carefully and then repeat what you have heard. In an actual test, the clock will indicate how much time you have to speak.</p><p>No time for preparation will be provided.</p>`:`<p>You will answer questions from an interviewer. Listen carefully and answer each question in English.</p>`;const body=`<section class="tfRefPanel tfTaskIntro"><h1>${title}</h1><div class="tfThinRule"></div>${copy}</section>`;tfRefShell({section:'Speaking',actions:tfVolumeButton()+tfActionButton('tfTaskBegin','Begin'),body});$('#volumeBtn').onclick=tfToggleVolumeControl;$('#tfTaskBegin').onclick=()=>renderQuestion();tfFixedNarration('speaking'+mode+'Intro',title+'. '+copy.replace(/<[^>]+>/g,' '),260)}
function tfErrorScreen(code='TC4000'){tfStopPromptAudio();const body=`<section class="tfErrorPage"><h1><span class="tfErrorTriangle">▲</span> ERROR</h1><div class="tfThinRule"></div><p>An error occurred! Please inform the assessment administrator that your test must be launched again. You will be able to continue from the point where the error occurred. [${escapeHtml(code)}]</p></section>`;tfRefShell({body})}
function tfSpeakingResponseSeconds(q,repeat){
  const explicit=Number(q.responseSeconds||0);if(explicit>0)return explicit;
  if(!repeat)return 45;
  const windows=[8,8,10,10,10,12,12];return windows[Math.min(session.qIndex,windows.length-1)]||8
}
function renderTFSpeaking(step,q,key){
  if(q.type==='tc4000_error'){tfErrorScreen(q.code||'TC4000');return}
  const repeat=q.type==='listen_repeat'||(q.type!=='interview'&&session.qIndex<7),mode=repeat?'repeat':'interview',introKey='speaking:'+mode;
  if(!session.tfTaskIntros?.[introKey]){tfSpeakingTaskIntro(repeat,step,q,key);return}
  stopTimer();
  const secs=tfSpeakingResponseSeconds(q,repeat),img=assetURL(q.image),actions=tfVolumeButton();
  const visual=img?`<img class="tfSpeakingImage" src="${img}" alt="Speaking task">`:(q.illustration==='zoo'?tfZooIllustration():`<img class="tfSpeakingImage speaker" src="${tfPickBuiltInAsset('lecture',q)}" alt="Speaking prompt speaker">`);
  const prompt=escapeHtml(q.prompt||(repeat?'Listen and repeat only once.':'Answer the question.'));
  const body=`<section class="tfSpeakingOfficial ${repeat?'repeat':'interview'}"><h1>${prompt}</h1><div class="tfSpeakingVisual">${visual}</div><div class="tfResponseCard"><div class="tfResponseLabel">RESPONSE TIME</div><div class="tfResponseTime"><span class="tfResponseMic">${tfSvgIcon('mic')}</span><strong id="respTimer">00:00:${String(secs).padStart(2,'0')}</strong></div></div><div class="tfSpeakStatus" id="speakStatus" aria-live="polite">Listening…</div></section>`;
  tfRefShell({section:'Speaking',meta:`Question ${session.qIndex+1} of ${step.count||11}`,actions,body,question:true,brand:'✱toefl ibt'});$('#volumeBtn').onclick=tfToggleVolumeControl;
  const startRec=async()=>{
    const state=$('#speakStatus'),counter=$('#respTimer');
    try{
      const stream=await navigator.mediaDevices.getUserMedia({audio:true}),rec=new MediaRecorder(stream),chunks=[];
      rec.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data)};
      rec.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());try{await window.reviewSaveRecording(key,new Blob(chunks,{type:rec.mimeType}));}catch(e){state.textContent='Recording could not be saved. ';const retry=document.createElement('button');retry.textContent='Retry saving';retry.onclick=rec.onstop;state.append(retry);return;}session.answers[key]={recorded:true,size:chunks.reduce((n,b)=>n+b.size,0)};state.textContent='';tfTone(520,.09,.035);setTimeout(nextQ,430)};
      state.textContent='';tfTone(860,.095,.045);await new Promise(r=>setTimeout(r,180));rec.start();
      const end=Date.now()+secs*1000;let left=secs;counter.textContent=`00:00:${String(left).padStart(2,'0')}`;
      const int=setInterval(()=>{left=Math.ceil((end-Date.now())/1000);counter.textContent=`00:00:${String(Math.max(0,left)).padStart(2,'0')}`;if(left<=0){clearInterval(int);rec.stop()}},1000)
    }catch(e){state.textContent='';setTimeout(()=>tfErrorScreen('TC4000'),400)}
  };
  setTimeout(()=>tfPlayTaskAudio({...q,spokenPrompt:''},startRec),260)
}

function renderAnswerWidget(q,ans,key){if(q.type==='free_response')return `<textarea id="freeAnswer" style="width:100%;height:280px;padding:14px">${escapeHtml(ans||'')}</textarea>`;if(q.type==='numeric')return `<input id="numericAnswer" class="inputAnswer" value="${escapeHtml(ans??'')}">`;if(q.type==='fill_letters')return `<div class="notice" style="font-size:16px;line-height:1.8">${escapeHtml(q.passage||'')}</div><input id="textAnswer" class="inputAnswer" style="width:100%" placeholder="Enter the completed words" value="${escapeHtml(ans||'')}">`;const choices=q.choices||['Choice A','Choice B','Choice C','Choice D'];return `<div class="choices">${choices.map((c,i)=>`<button class="choice ${ans===i?'selected':''}" data-choice="${i}"><span class="bubble">${String.fromCharCode(65+i)}</span><span>${escapeHtml(c)}</span></button>`).join('')}</div>`}
function wireAnswer(q,key){document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{session.answers[key]=+b.dataset.choice;renderQuestion()});const f=$('#freeAnswer');if(f)f.oninput=e=>session.answers[key]=e.target.value;const n=$('#numericAnswer');if(n)n.oninput=e=>session.answers[key]=e.target.value;const t=$('#textAnswer');if(t)t.oninput=e=>session.answers[key]=e.target.value}
function bbReviewPage(step){stopTimer();const count=questionCount(step),section=escapeHtml(step.label);app.innerHTML=`<div class="bb bbExact bbV11 bbReviewScreen"><div class="bbHeader exact"><div class="bbHeadLeft"><div class="bbSec">${section}</div><button class="bbDirectionsLink" id="directionsBtn">Directions <span>${bbMiniIcon('down')}</span></button></div><div class="bbTimer"><span id="timerText">${hiddenTimer?'••:••':formatTime(session.seconds)}</span><button id="hideTimer">${hiddenTimer?'Show':'Hide'}</button></div><div class="bbTools"><button class="bbIconTool" id="annotateBtn">${bbIcon('pen')}<span>Annotate</span></button><button class="bbIconTool" id="moreBtn">${bbIcon('more')}<span>More</span></button></div></div><div class="bbRail"></div><main class="bbReviewMain"><h1>Check Your Work</h1><p>Review your answers before you move on to the next module.</p><div class="bbReviewCard"><div class="bbReviewCardTop"><h2>${section} Questions</h2><div class="bbReviewLegend"><span><i class="unans"></i>Unanswered</span><span><i class="flag"></i>For Review</span></div></div><div class="bbReviewRule"></div><div class="bbReviewGrid">${Array.from({length:count},(_,i)=>{const k=step.id+':'+i,a=session.answers[k]!==undefined,f=session.flags[k];return `<button data-go="${i}" class="${a?'answered':'unanswered'} ${f?'flagged':''}">${i+1}${f?'<i></i>':''}</button>`}).join('')}</div></div></main><div class="bbRail bottom"></div><div class="bbTestFooter"><div class="bbStudent">${escapeHtml(bbCandidateName())}</div><div></div><div class="bbFooterNav"><button class="bbBack" id="reviewBack">Back</button><button class="bbNext" id="reviewNext">Next</button></div></div></div>`;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{session.qIndex=+b.dataset.go;if(session.seconds>0)startTimer();renderQuestion()});$('#reviewBack').onclick=()=>{if(session.seconds>0)startTimer();renderQuestion()};$('#reviewNext').onclick=()=>bbModuleOver();$('#hideTimer').onclick=toggleTimer;$('#directionsBtn').onclick=()=>bbDirectionsPopup(step);$('#annotateBtn').onclick=()=>bbOpenAnnotation(step.id+':'+session.qIndex);$('#moreBtn').onclick=helpModal;if(session.seconds>0)startTimer()}
function bbSpinner(){return `<span class="bbDotSpinner">${Array.from({length:12},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</span>`}
function bbModuleOver(){stopTimer();const current=session.base.steps[session.stepIndex];app.innerHTML=`<div class="bbModuleOver"><div><h1>This Module Is Over</h1><p>All your work has been saved.</p><p>You'll move on automatically in just a moment.</p><p>Do not refresh this page or exit the app.</p>${bbSpinner()}</div></div>`;setTimeout(()=>bbAfterModule(current),1550)}
function bbAfterModule(current){const ni=session.stepIndex+1;if(ni>=session.base.steps.length){finishExam();return}const n=session.base.steps[ni];if(n.type==='break'){session.stepIndex=ni;session.seconds=bbStepDuration(n);renderBreak();return}const sameSection=(current?.label||'')===(n?.label||'');if(sameSection&&n.type!=='break')beginStep(ni);else bbDirections(ni)}
function nextQ(){const step=session.base.steps[session.stepIndex];if(session.qIndex+1>=questionCount(step)){if(session.exam==='TOEFL'){tfEndCurrentStep();return}if(session.exam==='SAT'||session.exam==='AP'){bbReviewPage(step);return}endSectionConfirm();return}session.qIndex++;renderQuestion()}
function tfEndCurrentStep(){stopTimer();tfStopPromptAudio();const step=session.base.steps[session.stepIndex],next=session.base.steps[session.stepIndex+1];if(next&&next.label===step.label&&next.type===step.type&&session.seconds>0){tfEndModule(step,next);return}tfEndSection(step)}
function tfEndModule(step,next){const moduleNo=/2/.test(step.sub||step.id)?2:1,body=`<section class="tfRefPanel tfEndPanel"><h1>End of Module ${moduleNo}</h1><div class="tfThinRule"></div><p>Select <b>Next</b> to continue to Module ${moduleNo+1}.</p></section>`;tfRefShell({section:step.label,actions:tfActionButton('tfEndNext','Next'),body});$('#tfEndNext').onclick=nextStep;tfFixedNarration('endModule','End of Module '+moduleNo+'. Select Next to continue to Module '+(moduleNo+1)+'.',360)}
function tfEndSection(step){const body=`<section class="tfRefPanel tfEndPanel"><h1>End of ${escapeHtml(step.label)} Section</h1><div class="tfThinRule"></div><p>Thank you for completing the ${escapeHtml(step.label.toLowerCase())} section.</p></section>`;tfRefShell({section:step.label,actions:tfActionButton('tfEndNext','Next'),body});$('#tfEndNext').onclick=nextStep;tfFixedNarration('endSection','End of '+step.label+' Section. Thank you for completing the '+step.label.toLowerCase()+' section.',360)}
function prevQ(){if(session.qIndex>0){session.qIndex--;renderQuestion()}}
function endSectionConfirm(){if(session.exam==='TOEFL'){tfEndCurrentStep();return}showModal('Finish this section?',`<p>Once you continue, you may not return to this section.</p><div style="display:flex;justify-content:flex-end;gap:10px"><button class="tfBtn" data-close>Cancel</button><button class="tfBtn primary" id="confirmEnd">Continue</button></div>`);$('#confirmEnd').onclick=()=>{closeModal();nextStep()}}
function questionMenu(step,style){if(style==='bb'){bbReviewPage(step);return}if(style==='act'){let html=`<div class="actIndexList"><div class="actIndexRow info"><b>Help Screen</b><span>Answered</span></div><div class="actIndexRow info"><b>Information</b><span>Answered</span></div><div class="actIndexRow info"><b>Instructions</b><span>Answered</span></div>`;for(let i=0;i<questionCount(step);i++){const key=step.id+':'+i;html+=`<button class="actIndexRow" data-go="${i}"><b>${session.flags[key]?'🔖 ':''}Question ${i+1}</b><span>${session.answers[key]!==undefined?'Answered':''}</span></button>`}html+='</div>';showModal('INDEX',html)}else{let html=`<div class="bbGrid">`;for(let i=0;i<questionCount(step);i++){const key=step.id+':'+i;html+=`<button data-go="${i}" class="${session.answers[key]!==undefined?'answered':''}">${i+1}</button>`}html+='</div>';showModal('Review',html)}document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{session.qIndex=+b.dataset.go;closeModal();renderQuestion()})}
function actDropdown(which){closeActDrop();const b=which==='tools'?$('#toolsBtn'):$('#contrastBtn');const r=b.getBoundingClientRect(),d=el('div','actDrop');d.style.left=r.left+'px';if(which==='tools')d.innerHTML=`<button data-tool="eliminate">Answer Eliminator ${session.toolEliminate?'✓':''}</button><button data-tool="mask">Answer Masking ${session.toolMask?'✓':''}</button><button data-tool="line">Line Reader ${session.toolLine?'✓':''}</button><button data-tool="mag">Magnifier ${session.toolMag?'✓':''}</button>${session.base.steps[session.stepIndex].math?'<button data-tool="calc">Calculator</button>':''}`;else d.innerHTML=`<button data-contrast="normal">Normal</button><button data-contrast="high">High Contrast</button>`;document.body.appendChild(d);actToolOpen=d;d.onclick=e=>{const t=e.target.dataset.tool,c=e.target.dataset.contrast;if(t==='eliminate')session.toolEliminate=!session.toolEliminate;if(t==='mask')session.toolMask=!session.toolMask;if(t==='line')session.toolLine=!session.toolLine;if(t==='mag')session.toolMag=!session.toolMag;if(t==='calc'){closeActDrop();calculatorModal();return}if(c){document.body.classList.toggle('highContrast',c==='high')}closeActDrop();renderQuestion()}}
function closeActDrop(){if(actToolOpen){actToolOpen.remove();actToolOpen=null}}
function toolClass(){return `${session.toolMask?'maskText':''} ${session.toolLine?'lineReader':''}`}
function answeredCount(step){let n=0;for(let i=0;i<questionCount(step);i++)if(session.answers[step.id+':'+i]!==undefined)n++;return n}
function calculatorModal(){showModal('Calculator',`<div class="calc"><input class="calcDisplay" id="calcDisplay" readonly value="0"><div class="calcGrid">${['7','8','9','÷','4','5','6','×','1','2','3','−','0','.','=','+'].map(x=>`<button data-calc="${x}">${x}</button>`).join('')}</div></div>`);let expr='';document.querySelectorAll('[data-calc]').forEach(b=>b.onclick=()=>{let v=b.dataset.calc;if(v==='='){try{const safe=expr.replace(/÷/g,'/').replace(/×/g,'*').replace(/−/g,'-');if(!/^[0-9+\-*/. ()]+$/.test(safe))throw 0;expr=String(Function('return ('+safe+')')())}catch(e){expr='Error'}}else expr+=v;$('#calcDisplay').value=expr||'0'})}
function referenceModal(){showModal('Reference Sheet',`<h3>Math Reference</h3><p>Area of a circle: A = πr²</p><p>Circumference: C = 2πr</p><p>Pythagorean theorem: a² + b² = c²</p><p>Volume of a rectangular prism: V = lwh</p><p class="small">This simulator provides a compact reference preview. Exam packages can include additional permitted reference material.</p>`)}
function volumeModal(){showModal('Volume',`<label>Output volume</label><input type="range" min="0" max="100" value="70" style="width:100%;margin-top:18px"><p class="small">Use your device volume controls as needed.</p>`)}
function helpModal(){showModal('Help',`<p>Use the navigation controls to move among questions where the exam permits it.</p><p>Your responses are saved locally while the simulator is open.</p><p class="small">Keyboard shortcut: Esc closes this help window.</p>`)}
function showModal(title,body){closeModal();const sh=el('div','modalShade');sh.id='modalShade';sh.innerHTML=`<div class="modal"><div class="modalHead"><span>${escapeHtml(title)}</span><button class="modalClose" data-close>×</button></div><div class="modalBody">${body}</div></div>`;document.body.appendChild(sh);sh.onclick=e=>{if(e.target===sh||e.target.closest('[data-close]'))closeModal()}}
function closeModal(){$('#modalShade')?.remove()}
function assetURL(path){if(!path)return '';path=String(path);if(path.startsWith('assets/')||path.startsWith('./assets/'))return path.replace(/^\.\//,'');const p=session?.base?.package,u8=p?.files?.[path];if(!u8)return '';const key=(session.packageId||'pkg')+'|'+path;if(pkgCache[key])return pkgCache[key];const ext=String(path).toLowerCase().split('.').pop(),mime={mp3:'audio/mpeg',ogg:'audio/ogg',wav:'audio/wav',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',svg:'image/svg+xml'}[ext]||'application/octet-stream';return pkgCache[key]=URL.createObjectURL(new Blob([u8],{type:mime}))}
function mediaHTML(q){const u=assetURL(q?.image);return u?`<div style="margin:18px 0;text-align:center"><img src="${u}" alt="Question figure" style="max-width:100%;max-height:340px;object-fit:contain"></div>`:''}
function paragraphs(s=''){return String(s).split(/\n\n+/).map(p=>`<p>${escapeHtml(p)}</p>`).join('')}
function formatTime(sec,hms=false){sec=Math.max(0,Math.floor(sec||0));const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return (hms||h>0)?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function startTimer(){stopTimer();timerHandle=setInterval(()=>{if(!session)return;if(session.seconds>0)session.seconds--;const t=$('#timerText');if(t&&!hiddenTimer)t.textContent=t.closest('.tfReference')?formatTime(session.seconds,true):formatTime(session.seconds);const a=$('#actTimer');if(a&&!hiddenTimer)a.textContent='TOTAL TIME LEFT  '+formatTime(session.seconds,true);if(session.seconds<=0){stopTimer();if(session.exam==='TOEFL'){const step=session.base.steps[session.stepIndex];if(step?.type==='toefl-writing')tfExpireWritingTask();else tfEndCurrentStep()}else if(session.exam==='SAT'||session.exam==='AP'){const step=session.base.steps[session.stepIndex];if(step?.type==='bluebook'||step?.type==='ap-writing')bbReviewPage(step);else nextStep()}else nextStep()}},1000)}
function stopTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null}}
function toggleTimer(){hiddenTimer=!hiddenTimer;const t=$('#timerText');if(t)t.textContent=hiddenTimer?(t.closest('.tfReference')?'••:••:••':'••:••'):(t.closest('.tfReference')?formatTime(session.seconds,true):formatTime(session.seconds));const b=$('#hideTimer');if(b){if(b.classList.contains('tfHideTime'))b.innerHTML=tfIcon('eye-off')+`<span>${hiddenTimer?'Show Time':'Hide Time'}</span>`;else b.textContent=hiddenTimer?'Show':'Hide'}}
async function libraryModal(){const p=await dbAll();showModal('Exam Packages',`<div id="pkgList">${p.length?p.map(x=>`<div class="pkgRow"><div><b>${escapeHtml(x.title)}</b><div class="small">${escapeHtml(x.exam)} · ${escapeHtml(x.preset||'custom')}</div></div><button class="linkBtn danger" data-del="${escapeHtml(x.id)}">Remove</button></div>`).join(''):'<p>No imported packages yet.</p>'}</div><button class="tfBtn primary" id="modalImport">Import Package</button>`);$('#modalImport').onclick=()=>packageInput.click();document.querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{await dbDelete(b.dataset.del);closeModal();home()})}
packageInput.onchange=async()=>{const f=packageInput.files[0];if(!f)return;try{const buf=await f.arrayBuffer(),kind=f.name.toLowerCase().endsWith('.zip')?'zip':'json',pack=await decodePackage(buf,kind),m=pack.manifest;validateManifest(m);await dbPut({id:m.id||crypto.randomUUID(),title:m.title||f.name,exam:m.exam,preset:m.preset||'',kind,data:buf,importedAt:Date.now()});alert(`Imported: ${m.title||f.name}\nExam: ${m.exam}`);closeModal();home()}catch(e){alert('Import failed: '+e.message)}finally{packageInput.value=''}}
function validateManifest(m){if(!m||typeof m!=='object')throw Error('manifest.json is missing or invalid');if(!['TOEFL','SAT','AP','ACT'].includes(m.exam))throw Error('manifest.exam must be TOEFL, SAT, AP, or ACT');if(!m.title)throw Error('manifest.title is required')}
async function decodePackage(buf,kind){if(kind==='json'){const txt=new TextDecoder().decode(buf),manifest=JSON.parse(txt);return {manifest,sections:manifest.sectionsInline||{}}}const files=await unzip(buf);if(!files['manifest.json'])throw Error('ZIP must contain manifest.json at its root');const manifest=JSON.parse(await blobText(files['manifest.json']));const sections={};const map=manifest.sections||{};for(const [id,path] of Object.entries(map)){if(typeof path==='string'&&files[path])sections[id]=JSON.parse(await blobText(files[path]));else if(path&&typeof path==='object')sections[id]=path}return {manifest,sections,files}}
async function blobText(u8){return new TextDecoder().decode(u8)}
async function unzip(buffer){const dv=new DataView(buffer),u8=new Uint8Array(buffer);let e=-1;for(let i=u8.length-22;i>=Math.max(0,u8.length-66000);i--){if(dv.getUint32(i,true)===0x06054b50){e=i;break}}if(e<0)throw Error('Not a valid ZIP file');const count=dv.getUint16(e+10,true),cdOff=dv.getUint32(e+16,true);let p=cdOff;const out={};for(let n=0;n<count;n++){if(dv.getUint32(p,true)!==0x02014b50)throw Error('ZIP central directory is invalid');const method=dv.getUint16(p+10,true),cs=dv.getUint32(p+20,true),us=dv.getUint32(p+24,true),nl=dv.getUint16(p+28,true),xl=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true),lo=dv.getUint32(p+42,true);const name=new TextDecoder().decode(u8.slice(p+46,p+46+nl));const lnl=dv.getUint16(lo+26,true),lxl=dv.getUint16(lo+28,true),start=lo+30+lnl+lxl,comp=u8.slice(start,start+cs);let data;if(method===0)data=comp;else if(method===8){if(typeof DecompressionStream==='undefined')throw Error('This browser cannot decompress ZIP deflate data');const ds=new DecompressionStream('deflate-raw');data=new Uint8Array(await new Response(new Blob([comp]).stream().pipeThrough(ds)).arrayBuffer())}else throw Error('Unsupported ZIP compression method '+method);out[name]=data;p+=46+nl+xl+cl}return out}
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.ctrlKey&&e.key.toLowerCase()==='i'){e.preventDefault();packageInput.click()}if(e.ctrlKey&&e.shiftKey&&e.key.toLowerCase()==='h'){home()}})
