function __previewRoute(){const m=new URLSearchParams(location.search).get('preview');if(!m)return false;const exam='SAT',base=JSON.parse(JSON.stringify(officialDefaults[exam]));session={exam,base,stepIndex:0,qIndex:0,answers:{'rw1:0':1,'rw1:1':0,'rw1:4':2,'rw1:5':1,'rw1:6':3,'rw1:7':0},flags:{'rw1:2':true,'rw1:3':true},routes:{},seconds:0,startedAt:Date.now(),packageId:'preview',tfAssetPicks:{},tfTaskIntros:{},annotations:{},scrollStates:{},eliminated:{}};currentExam=exam;if(m==='preparing')bbPreparing(0);else if(m==='directions')bbDirections(0);else if(m==='question'){session.seconds=32*60;renderBluebook(base.steps[0])}else if(m==='review'){session.seconds=0;bbReviewPage(base.steps[0])}else if(m==='module-over')bbModuleOver();else if(m==='break'){session.stepIndex=2;base.steps[2].duration=180;renderBreak()}else if(m==='finish')finishExam();return true}

